"""State observation preserves temporal, simultaneous and source boundaries."""
import unittest
import state_trigger_fixture as fixtures

class StateTriggerBoundaryTests(fixtures.StateTriggerFixture,unittest.TestCase):
    def test_actual_cloudshift_transient_absence_queues_before_the_other_creature_returns(self):
        session=self.session(611651030);source=self.add(session.engine,'Emperor Crocodile',zone='hand');other=self.add(session.engine,'Grizzly Bears');blink=self.add(session.engine,'Cloudshift',zone='hand');self.add(session.engine,'Plains');self.assert_closed(session,source);self.assert_closed(session,blink)
        self.prepare(session,mana={'C':3,'G':1});self.checkpoint(session);self.cast(session,'A',source);self.settle(session);self.cast(session,'A',blink,[other.ref]);self.resolve_top(session);self.assertEqual('battlefield',session.state.cards[other.object_id].zone);self.assertEqual(1,self.trigger_count(session,source));session=self.replay(session,load=True);self.settle(session);self.assertEqual('graveyard',session.state.cards[source.object_id].zone);self.replay(session,load=True)

    def test_actual_old_pending_instance_cannot_sacrifice_a_bounced_and_recast_source(self):
        session=self.session(611651040);source=self.add(session.engine,'Emperor Crocodile',zone='hand');other=self.add(session.engine,'Grizzly Bears',zone='hand');self.add(session.engine,'Vedalken Orrery');bounce=self.add(session.engine,'Unsummon',seat='B',zone='hand');counter=self.add(session.engine,'Stifle',seat='B',zone='hand');self.assert_closed(session,source)
        self.prepare(session,mana={'C':7,'G':3});session.state.players['B'].mana_pool['U']=2;self.checkpoint(session);self.cast_for(session,'A',source,reserve={'C':4,'G':2});self.resolve_top(session);old_identity=session.state.cards[source.object_id].logical_object_id;old_ref=next(i.ref for i in session.state.stack if i.source_object_id==source.object_id)
        self.cast_for(session,'B',bounce,[source.ref],reserve={'U':1});self.resolve_top(session);self.cast_for(session,'A',source,reserve={'C':1,'G':1});self.resolve_top(session);self.assertNotEqual(old_identity,session.state.cards[source.object_id].logical_object_id);self.assertEqual(2,self.trigger_count(session,source));new_ref=next(i.ref for i in session.state.stack if i.source_object_id==source.object_id and i.ref!=old_ref)
        self.cast(session,'A',other);self.resolve_top(session);self.cast(session,'B',counter,[new_ref]);self.resolve_top(session);self.assertEqual(1,self.trigger_count(session,source));session=self.replay(session,load=True);self.settle(session);self.assertEqual('battlefield',session.state.cards[source.object_id].zone);self.replay(session,load=True)

    def test_actual_control_change_preserves_old_pending_owner_then_retriggers_for_new_controller(self):
        session=self.session(611651050);source=self.add(session.engine,'Emperor Crocodile',zone='hand');steal=self.add(session.engine,'Act of Treason',seat='B',zone='hand');self.add(session.engine,'Vedalken Orrery',seat='B');self.assert_closed(session,source);self.assert_closed(session,steal)
        self.prepare(session,mana={'C':3,'G':1});session.state.players['B'].mana_pool.update({'C':2,'R':1});self.checkpoint(session);self.cast(session,'A',source);self.resolve_top(session);self.cast(session,'B',steal,[source.ref]);self.resolve_top(session);self.assertEqual('B',session.state.cards[source.object_id].controller);self.assertEqual(1,self.trigger_count(session,source));self.assertEqual('A',next(i.controller for i in session.state.stack if i.source_object_id==source.object_id))
        self.resolve_top(session);self.assertEqual('battlefield',session.state.cards[source.object_id].zone);self.assertEqual(1,self.trigger_count(session,source));self.assertEqual('B',next(i.controller for i in session.state.stack if i.source_object_id==source.object_id));session=self.replay(session,load=True);self.settle(session);self.assertEqual('graveyard',session.state.cards[source.object_id].zone);self.assertIn(source.object_id,session.state.players['A'].zones['graveyard']);self.replay(session,load=True)

    def test_actual_simultaneous_destruction_of_source_and_other_creature_creates_no_state_trigger(self):
        session=self.session(611651060);other=self.add(session.engine,'Grizzly Bears');source=self.add(session.engine,'Emperor Crocodile',zone='hand');sweep=self.add(session.engine,'Day of Judgment',zone='hand');self.add(session.engine,'Stifle',seat='B',zone='hand');self.add(session.engine,'Island',seat='B');self.assert_closed(session,source);self.assert_closed(session,sweep)
        self.prepare(session,mana={'C':5,'G':1,'W':2});self.checkpoint(session);self.cast_for(session,'A',source,reserve={'C':2,'W':2});self.settle(session);self.cast(session,'A',sweep);self.resolve_top(session);self.assertEqual('graveyard',session.state.cards[source.object_id].zone);self.assertEqual('graveyard',session.state.cards[other.object_id].zone);self.assertEqual(0,self.trigger_count(session,source));self.replay(session,load=True)

    def test_actual_simultaneous_artifact_losses_queue_both_controllers_in_apnap_order(self):
        session=self.session(611651070);source=self.add(session.engine,'Covetous Dragon',zone='hand');foreign=self.add(session.engine,'Covetous Dragon',seat='B',ref='foreign-covetous');self.add(session.engine,'Memnite');self.add(session.engine,'Memnite',seat='B',ref='foreign-artifact');sweep=self.add(session.engine,'Pyroclasm',zone='hand');self.add(session.engine,'Mountain');self.add(session.engine,'Wastes');self.assert_closed(session,source);self.assert_closed(session,foreign);self.assert_closed(session,sweep)
        self.prepare(session,mana={'C':4,'R':1});self.checkpoint(session);self.cast(session,'A',source);self.settle(session);self.cast(session,'A',sweep);self.resolve_top(session);triggers=[i for i in session.state.stack if i.source_object_id in {source.object_id,foreign.object_id}];self.assertEqual(['A','B'],[i.controller for i in triggers]);session=self.replay(session,load=True);self.settle(session)
        for card in (source,foreign):self.assertEqual('graveyard',session.state.cards[card.object_id].zone)
        self.replay(session,load=True)
